INSERT IGNORE INTO seo_page_overrides(path,meta_title,seo_h1,meta_description,intro_text,index_catalog) VALUES
('/konkursy/pedagogi/nachalnaya-shkola/','Конкурсы для педагогов начальной школы — условия участия и дипломы','Конкурсы для педагогов начальной школы','Выберите конкурс для педагогов начальной школы: изучите требования к работе, условия участия и оформления диплома, подходящего для профессионального портфолио.','Подборка конкурсов для педагогов начальных классов. Откройте карточку, чтобы проверить тему, требования к работе, стоимость и вид итогового документа. Учёт диплома при аттестации зависит от требований вашей комиссии.',1),
('/olimpiady/pedagogi/nachalnaya-shkola/','Олимпиады для педагогов начальной школы — задания и условия','Олимпиады для педагогов начальной школы','Подберите олимпиаду для педагогов начальной школы: ознакомьтесь с темой, заданиями, условиями прохождения и получения документа в карточке мероприятия.','Здесь собраны олимпиады, отнесённые к педагогам 1–4 классов. Это профессиональные задания для учителей. Для учеников используйте отдельные каталоги школьных олимпиад по классам.',1),
('/vebinary/pedagogi/nachalnaya-shkola/','Вебинары для педагогов начальной школы — темы и записи','Вебинары для педагогов начальной школы','Выберите вебинар для педагогов начальной школы: изучите тему, сведения о спикере, формат просмотра и условия оформления именного документа участника.','Вебинары и видеолекции, связанные с работой педагогов начальных классов. В карточке указаны тема, спикер, формат, порядок участия и условия оформления сертификата.',1),
('/kursy/povyshenie-kvalifikatsii/nachalnaya-shkola/','Курсы повышения квалификации для учителей начальных классов — дистанционно','Курсы повышения квалификации для учителей начальных классов','Сравните программы повышения квалификации для учителей начальных классов: темы, часы, стоимость, содержание обучения и условия получения удостоверения.','Программы повышения квалификации, связанные с начальной школой. Сравните темы, объём часов, стоимость и условия обучения. В карточке программы указаны содержание, преподаватели и итоговый документ. Программы переподготовки доступны в отдельном разделе.',1),
('/kursy/nachalnaya-shkola/','Курсы для начальной школы — повышение квалификации и переподготовка','Курсы для начальной школы: КПК и переподготовка','Сравните курсы для начальной школы: программы повышения квалификации и профессиональной переподготовки, темы, часы, стоимость и условия обучения.','Общий каталог объединяет два вида обучения: повышение квалификации и профессиональную переподготовку. Проверьте вид программы и выдаваемый документ в карточке выбранного курса.',1);
